<script>import {dollars} from '$lib/format.js';export let data;export let form;</script>
<div class="heading"><div><a href="/dashboard">← Dashboard</a><h1>{data.group.name}</h1><p class="muted">{data.group.memberCount} member{data.group.memberCount===1?'':'s'}</p></div><div class="heading-actions">{#if data.group.isCreator}<a class="button secondary" href={'/groups/'+data.group.id+'/settings'}>Group settings</a>{/if}<a class="button" href={'/groups/'+data.group.id+'/expenses/new'}>+ Add expense</a></div></div>
{#if form?.error}<p class="error" role="alert">{form.error}</p>{/if}{#if form?.success}<p class="success" role="status">{form.success}</p>{/if}
{#if data.group.isCreator && data.joinRequests.length}<section class="card requests"><div class="title"><h2>Join requests</h2><span class="muted">Only you can approve these</span></div>{#each data.joinRequests as joinRequest}<div class="request"><span><b>{joinRequest.name}</b><small>{joinRequest.email}</small></span><span class="request-actions"><form method="POST" action="?/approve"><input type="hidden" name="requestId" value={joinRequest.id} /><button class="button" type="submit">Approve</button></form><form method="POST" action="?/decline"><input type="hidden" name="requestId" value={joinRequest.id} /><button class="button secondary" type="submit">Decline</button></form></span></div>{/each}</section>{/if}
<section class="card"><div class="title"><h2>Expenses</h2><span class="muted">Track who has paid</span></div>{#if data.expenses.length}{#each data.expenses as e}<div class="expense"><div class="expense-main"><span><b>{e.description}</b><small>{e.date} · paid by {e.payerName}</small></span><strong>{dollars(e.amount)}</strong></div><div class="expense-actions"><a class="button secondary" href={'/groups/'+data.group.id+'/expenses/'+e.id+'/edit'}>Edit</a><span class="muted">{e.splits.filter((split) => split.paid).length}/{e.splits.length} paid</span></div><div class="payments"><b>Members who have paid</b>{#each e.splits as split}<form method="POST" action="?/togglePaid"><input type="hidden" name="expenseId" value={e.id} /><input type="hidden" name="memberId" value={split.userId} /><button class:paid={split.paid} class="payment" type="submit" aria-pressed={split.paid}><span class="checkbox">{split.paid ? '✓' : ''}</span>{split.name}<small>{dollars(split.shareCents)}</small></button></form>{/each}</div></div>{/each}{:else}<div class="empty"><p>No expenses yet. Add the first shared cost.</p><a class="button secondary" href={'/groups/'+data.group.id+'/expenses/new'}>Add expense</a></div>{/if}</section>
<style>.heading{align-items:end;display:flex;justify-content:space-between;margin:2rem 0}.heading h1{font-size:2.6rem;margin:.7rem 0 .2rem}.heading-actions{display:flex;gap:.6rem}.muted,small{color:#58746b}.card{margin-bottom:1.25rem}.title{align-items:center;display:flex;justify-content:space-between}.title h2{font-size:1.2rem;margin:0}.request,.expense{border-top:1px solid #e6efeb;padding:1rem 0}.request span:first-child{display:grid;gap:.2rem}.request-actions{display:flex;gap:.5rem}.request-actions form{margin:0}.success{background:#e6f2ed;border:1px solid #b8deca;border-radius:8px;color:#146c52;padding:.75rem}.expense-main,.expense-actions{align-items:center;display:flex;gap:1rem;justify-content:space-between}.expense-main span{display:grid;gap:.2rem}.expense-main strong{color:#146c52}.expense-actions{margin-top:.75rem}.payments{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1rem}.payments>b{flex-basis:100%;font-size:.9rem}.payments form{margin:0}.payment{align-items:center;background:#f6f8f7;border:1px solid #dce8e3;border-radius:8px;color:#18332c;cursor:pointer;display:flex;font:inherit;gap:.45rem;padding:.5rem .7rem}.payment.paid{background:#e6f2ed;border-color:#b8deca;color:#146c52}.payment small{margin-left:.25rem}.checkbox{align-items:center;border:1px solid #9eb9ad;border-radius:4px;display:inline-flex;height:1.1rem;justify-content:center;width:1.1rem}.empty{text-align:center;padding:2rem;color:#58746b}@media(max-width:600px){.heading{align-items:flex-start;gap:1rem;flex-direction:column}.heading-actions{flex-wrap:wrap}.request{align-items:flex-start;flex-direction:column}.request-actions{width:100%}.request-actions form{flex:1}.request-actions button{width:100%}.expense-actions{align-items:flex-start;flex-direction:column}}
</style>
